import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {execFileSync} from 'node:child_process';
import {createHash} from 'node:crypto';
const base='80f35eaddfbbee4b785616a331cf030da241997c',live='6dd42a5df6ed0fb29a2a0c0922cc67b24a2ace36',folder='docs/learning-goals-20261101/',floor='docs/appearance-floor-20261031/floor.json';
const git=(...a)=>execFileSync('git',a,{maxBuffer:128e6}),sha=b=>createHash('sha256').update(b).digest('hex'),lines=b=>b.toString().trim().split('\n').filter(Boolean),sort=a=>a.sort((a,b)=>a.localeCompare(b));
const roots=['app','components','hooks','data','lib','public','scripts','db','drizzle','.github','AGENTS.md','PUBLICATIE.md','VORMGEVING-VASTGEZET.md','docs/appearance-floor-20261031','docs/KLINK-DOCENTHANDLEIDING.md','vite.config.ts','next.config.ts','package.json','package-lock.json','wrangler.jsonc'];
export function verifyLearningGoalsRelease(read=readFileSync){
 const json=f=>JSON.parse(read(f)),r=json('docs/klink-owner-release-learning-goals-20261101.json');assert.equal(r.approvedBy,'Nico');assert(r.publicationApproved&&r.appearanceChangeApproved);assert.equal(r.baselineSourceCommit,base);assert.equal(r.liveSourceCommit,live);assert(r.userRequest.includes('Zet Wat oefen je? met de gekleurde labels boven Zo oefen je'));git('merge-base','--is-ancestor',live,base);git('merge-base','--is-ancestor',base,'HEAD');
 const changed=sort([...new Set([...lines(git('diff','--name-only',base,'--',...roots)),...lines(git('ls-files','--others','--exclude-standard','--',...roots))])]);assert.deepEqual(changed,sort([...r.changedFiles,floor,r.approval]));assert.deepEqual(sort(Object.keys(r.files)),r.changedFiles);for(const[f,h]of Object.entries(r.files))assert.equal(sha(read(f)),h,f);for(const[f,h]of Object.entries(r.evidenceFiles))assert.equal(sha(read(f)),h,f);
 const runtime=changed.filter(f=>/^(app|components|hooks|data|lib|public|db|drizzle)\//.test(f));assert.deepEqual(runtime,sort(['app/learner-layout.css','components/product/imported-practice-surface.tsx','components/product/package-exercise-browser.tsx','components/product/package-group-practice.tsx','components/product/learner-exercise-info.tsx','data/klink-learning-goals.json','lib/learning-goals.ts']));
 assert.equal(git('diff','--name-only',base,'--','hooks','data','public','db','drizzle','.github','AGENTS.md','package.json','package-lock.json','wrangler.jsonc',':(exclude)data/klink-learning-goals.json').length,0,'All original content, media, progress/keyboard contracts, dependencies and workflows preserved');assert(read('app/learner-layout.css').toString().startsWith(git('show',base+':app/learner-layout.css').toString()));
 const matrix=json(folder+'approved-matrix.json'),data=json('data/klink-learning-goals.json');assert.deepEqual(data.families,matrix.families);assert.equal(Object.keys(data.goals).length,97);for(const g of matrix.goals)assert.deepEqual(data.goals[g.id],Object.fromEntries(['family','displayLabels','learnerText'].map(k=>[k,g[k]])));
 const oldFloor=JSON.parse(git('show',base+':'+floor));assert.deepEqual(json(floor),{...oldFloor,approvedUpdates:[...oldFloor.approvedUpdates,r.approval]});const approval=json(r.approval);assert.equal(approval.userRequest,r.userRequest);assert(approval.publicationApproved&&approval.appearanceChangeApproved);assert.deepEqual(approval.files,Object.fromEntries(runtime.map(f=>[f,r.files[f]])));
 const browser=json(folder+'local/browser/checks.json');assert.equal(browser.checks.length,108);assert.deepEqual(browser.errors,[]);for(const c of browser.checks)for(const k of['fits','goalBeforeHow','controlsReachable','keyboardContained','escapeFocusRestored','touchReturn','exercisePreserved','storagePreserved'])assert.equal(c[k],true,k);
 const sheets=json(folder+'local/sheets/checks.json');assert.equal(sheets.checks.length,16);assert.deepEqual(sheets.errors,[]);assert(sheets.checks.every(c=>c.dialogFits&&c.toolbarFits&&c.keyboardContained&&c.focusRestored&&c.exercisePreserved));
 const scroll=json(folder+'keyboard-scroll.json');assert(scroll.after.top>scroll.before.top&&scroll.controls.every(c=>c.visible));
 const retention=json(folder+'local/retention/checks.json');assert.equal(retention.checks.length,12);assert.deepEqual(retention.errors,[]);assert(retention.checks.every(c=>c.answerPreserved&&c.progressPreserved&&c.reloadPreserved&&c.keyboardContained));
 const writing=json(folder+'local/writing/checks.json');assert.equal(writing.checks.length,16);assert.equal(writing.audioNext.length,12);assert.equal(writing.native.length,2);assert.deepEqual(writing.errors,[]);const imported=json(folder+'local/imported/browser-checks.json');assert.equal(imported.checks.length,9);assert.deepEqual(imported.errors,[]);
 const proof=json(folder+'verification.json');for(const k of['types','lint','allGoalMappings','approvedLabelsAndColors','keyboard','mobileTouch','teacherPrivacy','nativeAudioAndNext','answersAndProgress','contentMediaAndStorageUnchanged','localOnly'])assert.equal(proof[k],true,k);assert.equal(proof.catalogueVariants,99632);assert.equal(proof.uniqueExerciseIds,67936);
 const backup=json(folder+'backup.json');assert(backup.verified&&backup.fullReadback&&backup.zipIntegrity&&backup.driveId);assert.deepEqual(backup.files,r.files);assert.deepEqual(backup.evidenceFiles,r.evidenceFiles);return r;
}
export function readBeforeLearningGoals(file,r,read=readFileSync){return r.changedFiles.includes(file)||file===floor?git('show',base+':'+file):read(file);}
